import xlog1pyf = require( './index' );


// TESTS //

// The function returns a number...
{
	xlog1pyf( 8, 2 ); // $ExpectType number
}

// The compiler throws an error if the function is provided values other than two numbers...
{
	xlog1pyf( true, 3 ); // $ExpectError
	xlog1pyf( false, 2 ); // $ExpectError
	xlog1pyf( '5', 1 ); // $ExpectError
	xlog1pyf( [], 1 ); // $ExpectError
	xlog1pyf( {}, 2 ); // $ExpectError
	xlog1pyf( ( x: number ): number => x, 2 ); // $ExpectError

	xlog1pyf( 9, true ); // $ExpectError
	xlog1pyf( 9, false ); // $ExpectError
	xlog1pyf( 5, '5' ); // $ExpectError
	xlog1pyf( 8, [] ); // $ExpectError
	xlog1pyf( 9, {} ); // $ExpectError
	xlog1pyf( 8, ( x: number ): number => x ); // $ExpectError

	xlog1pyf( [], true ); // $ExpectError
	xlog1pyf( {}, false ); // $ExpectError
	xlog1pyf( false, '5' ); // $ExpectError
	xlog1pyf( {}, [] ); // $ExpectError
	xlog1pyf( '5', ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided insufficient arguments...
{
	xlog1pyf(); // $ExpectError
	xlog1pyf( 3 ); // $ExpectError
}
